    ic=pd.Series(rows[h],index=dates[h]);
    for n in [63,126,252]:
        z=ic.iloc[-n:]; print('recent',h,n,'IC',round(z.mean(),6),'ICIR',round(z.mean()/z.std(ddof=1),6) if len(z)>1 else None)
